def import_legacy_users(apps, schema_editor):
    database = schema_editor.connection.alias
    LegacyUser = apps.get_model("security", "User")
    DjangoUser = apps.get_model("auth", "User")
    UserRole = apps.get_model("security", "UserRole")
    user_ids = {}

    for legacy_user in LegacyUser.objects.using(database).order_by("id").iterator():
        matching_users = DjangoUser.objects.using(database).filter(
            email__iexact=legacy_user.email
        )
        if legacy_user.email and matching_users.count() == 1:
            django_user = matching_users.get()
        else:
            username = f"huellavet_legacy_{legacy_user.pk}"
            suffix = 1
            while DjangoUser.objects.using(database).filter(username=username).exists():
                username = f"huellavet_legacy_{legacy_user.pk}_{suffix}"
                suffix += 1

            password = make_password(None)
            try:
                identify_hasher(legacy_user.password_hash)
            except (TypeError, ValueError):
                pass
            else:
                password = legacy_user.password_hash

            django_user = DjangoUser.objects.using(database).create(
                username=username,
                email=legacy_user.email,
                first_name=legacy_user.name[:150],
                password=password,
                is_active=legacy_user.is_active,
                is_staff=False,
                is_superuser=False,
            )

        legacy_user.auth_user_id = django_user.pk
        legacy_user.save(using=database, update_fields=["auth_user"])
        user_ids[legacy_user.pk] = django_user.pk

    for assignment in UserRole.objects.using(database).iterator():
        assignment.auth_user_id = user_ids[assignment.user_id]
        assignment.save(using=database, update_fields=["auth_user"])


